   * 加载入口页面、初始化UI基础样式
   * @param {window.WindowStage} windowStage - 窗口阶段
   * @returns {Promise<void>} 无返回值的Promise
   */
  async onWindowStageCreate(windowStage: window.WindowStage): Promise<void> {
    await this.initIBestORM();
    windowStage.loadContent('view/EntryPage', (_) => {
      IBestUIInitializer.initIBestUI(windowStage, this.context);
    });
  }

  /**
   * 应用销毁时调用
   * 释放应用上下文、注销路由
   * @returns {void} 无返回值
   */
  onDestroy(): void {
    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onDestroy');
  }

  /**
   * 窗口销毁时调用
   * 释放窗口资源
   * @returns {void} 无返回值
   */
  onWindowStageDestroy(): void {
  }

  /**
   * 应用进入前台时调用
   * 刷新应用状态、重新注册路由
   * @returns {void} 无返回值
   */
  onForeground(): void {
  }

  /**
   * 应用进入后台时调用
   * 暂停应用状态、注销路由
   * @returns {void} 无返回值
   */
  onBackground(): void {
  }

  /**
   * 初始化 IBest ORM 数据库
   */
  async initIBestORM(): Promise<void> {
    await IBestORMInit(this.context, { name: "app.db" });
  }

  /**
   * 注册路由
