    this.isLoading = true;
    this.currentPage = 1;
    this.loadHomeData();
  }

  /**
   * 重试请求
   * @returns {void} 无返回值
   */
  retryRequest(): void {
    this.uiState = BaseNetWorkListUiState.LOADING;
    this.currentPage = 1;
    this.loadHomeData();
  }
}
