from __future__ import annotations

from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import re
import signal
import sqlite3
import subprocess
import sys
import time
import urllib.parse
import urllib.request

from hypium import BY
from harness.device import find_hdc
from harness.driver import HarnessTestCase

ROOT = Path(__file__).resolve().parents[4]
FIXTURE = ROOT / "traces/fixture-ui"
OUT = FIXTURE / "verification"
DEVICE = "127.0.0.1:11239"
BUNDLE = "com.joker.coolmall.fixture28"
BASE = "http://127.0.0.1:17028"
FIELDS = ["contact", "phone", "province", "city", "district", "address", "isDefault"]
WRITES = {"/app/user/address/" + action for action in ["add", "update", "delete"]}


def now():
    return datetime.now(timezone.utc).isoformat()


def save(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")


class FixtureAdmin:
    def request(self, method, path, body=None, timeout=10):
        assert path.startswith("/__admin/") and not path.startswith("//")
        url = BASE + path
        parsed = urllib.parse.urlsplit(url)
        assert (parsed.scheme, parsed.hostname, parsed.port) == ("http", "127.0.0.1", 17028)
        request = urllib.request.Request(url, method=method,
            data=json.dumps(body).encode() if body is not None else None,
            headers={"Content-Type": "application/json"})
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, headers, newurl):
                raise AssertionError("Fixture admin redirect refused before network send")
        with urllib.request.build_opener(NoRedirect()).open(request, timeout=timeout) as response:
            assert response.geturl() == url, "Fixture admin must never redirect"
            return json.load(response)

    def health(self):
        return self.request("GET", "/__admin/health")

    def snapshot(self):
        return self.request("GET", "/__admin/snapshot")

    def events(self, after):
        return self.request("GET", f"/__admin/events?after={int(after)}")

    def configure(self, case, rules=None):
        return self.request("POST", "/__admin/config", {
            "caseId": case, "clearRules": True, "rules": rules or []})


class FixtureUITestCase(HarnessTestCase):
    @classmethod
    def setUpClass(cls):
        if cls.device_sn != DEVICE:
            raise RuntimeError("Fixture tests operate only 127.0.0.1:11239")
        super().setUpClass()
        cls.driver.set_implicit_wait_time(.5)

    def setUp(self):
        self.case = self._testMethodName
        self.dir = OUT / "cases" / self.case
        self.dir.mkdir(parents=True, exist_ok=True)
        self.actions = []
        self.windows = []
        self.admin = FixtureAdmin()
        health = self.admin.health()
        self.assertTrue(health["ok"], "Fixture setup: local server unhealthy")
        self.admin.request("POST", "/__admin/reset", {})
        self.admin.configure(self.case)
        self.initial = self.db_snapshot("initial")
        self.assertEqual({row["id"] for row in self.initial["addresses"]}, {2801, 2802})
        self.assertTrue(self.row(2801)["isDefault"])
        self.assertFalse(self.row(2802)["isDefault"])
        self.restart_app()

    def tearDown(self):
        # Persist the action log even if a screenshot or server snapshot fails.
        try:
            self.snapshot("final")
            self.db_snapshot("final")
        finally:
            save(self.dir / "actions.json", self.actions)
            save(self.dir / "windows.json", self.windows)

    def event(self, action, **values):
        self.actions.append({"utc": now(), "monotonic": time.monotonic(),
                             "action": action, **values})

    def restart_app(self):
        self.driver.stop_app(BUNDLE)
        self.driver.start_app(BUNDLE, page_name="EntryAbility", wait_time=2)
        self.event("cold-start", bundle=BUNDLE, ability="EntryAbility")

    def db_snapshot(self, label):
        snapshot = self.admin.snapshot()
        self.assertIsInstance(snapshot.get("addresses"), list, "Fixture snapshot contract")
        save(self.dir / f"db-{label}.json", snapshot)
        return snapshot

    def row(self, address_id):
        return next(item for item in self.admin.snapshot()["addresses"] if item["id"] == address_id)

    def backup_database(self, label):
        health = self.admin.health()
        database = Path(health["dbPath"])
        if not database.is_absolute():
            database = ROOT / database
        database = database.resolve()
        self.assertTrue(database.is_relative_to((FIXTURE / "evidence").resolve()),
                        "Refuse reading a database outside fixture evidence")
        target = self.dir / f"sqlite-{label}.sqlite"
        with sqlite3.connect(f"file:{database.as_posix()}?mode=ro", uri=True) as source:
            with sqlite3.connect(target) as backup:
                source.backup(backup)
                schema = backup.execute("SELECT name,sql FROM sqlite_master WHERE type='table'").fetchall()
                tables = {}
                for table, _ in schema:
                    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", table):
                        raise AssertionError("Unexpected fixture SQLite table name")
                    cursor = backup.execute(f'SELECT * FROM "{table}"')
                    columns = [column[0] for column in cursor.description]
                    tables[table] = [dict(zip(columns, row)) for row in cursor.fetchall()]
        save(self.dir / f"sqlite-{label}.json", {"source": str(database), "schema": schema,
            "tables": tables, "backup_sha256": hashlib.sha256(target.read_bytes()).hexdigest()})
        self.event("sqlite-safe-backup", label=label, source=str(database), target=str(target))

    def restart_server(self):
        self.driver.stop_app(BUNDLE)
        before = self.admin.health()
        self.backup_database("before-service-restart")
        snapshot = self.admin.snapshot()["addresses"]
        database = Path(before["dbPath"])
        if not database.is_absolute():
            database = ROOT / database
        self.assertTrue(database.resolve().is_relative_to((FIXTURE / "evidence").resolve()))
        pid = int(before["pid"])
        self.assertGreater(pid, 1)
        self.assertNotEqual(pid, os.getpid())
        os.kill(pid, signal.SIGTERM)
        deadline = time.monotonic() + 10
        while time.monotonic() < deadline:
            try:
                self.admin.health()
            except Exception:
                break
            time.sleep(.1)
        else:
            self.fail("Owned fixture server did not stop")
        args = [sys.executable, str(FIXTURE / "server/fixture_server.py"),
                "--host", "127.0.0.1", "--port", "17028", "--db", str(database),
                "--events", str(FIXTURE / "evidence/http-events.jsonl")]
        with (self.dir / "server-restart.log").open("ab") as output:
            child = subprocess.Popen(args, cwd=ROOT, stdout=output, stderr=subprocess.STDOUT,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        deadline = time.monotonic() + 15
        after = None
        while time.monotonic() < deadline:
            try:
                after = self.admin.health()
                if after.get("ok"):
                    break
            except Exception:
                pass
            time.sleep(.1)
        self.assertIsNotNone(after, "Fixture process restart failed")
        self.assertNotEqual(after["pid"], before["pid"])
        self.assertGreaterEqual(after["maxSeq"], before["maxSeq"])
        self.assertEqual(self.admin.snapshot()["addresses"], snapshot,
                         "Real process restart must preserve full SQLite rows")
        self.event("service-restart", old_health=before, new_health=after,
                   argv=args, spawned_pid=child.pid, database_reset=False)
        self.backup_database("after-service-restart")
        self.restart_app()

    def snapshot(self, label):
        stem = re.sub(r"[^A-Za-z0-9_-]", "_", label)
        self.driver.capture_screen(str(self.dir / f"{stem}.jpeg"))
        remote = f"/data/local/tmp/fixture28-{stem}.json"
        for args in [("shell", "uitest", "dumpLayout", "-p", remote),
                     ("file", "recv", remote, str((self.dir / f"{stem}.json").relative_to(ROOT)))]:
