class FixtureState:
    def __init__(self, db, events):
        self.db = db.resolve()
        self.events = events.resolve()
        self.db.parent.mkdir(parents=True, exist_ok=True)
        self.events.parent.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        self.started_at = utc()
        self.case_id = "fixture-initialization"
        self.rules = []
        with self.connect() as con:
            con.executescript("""
                PRAGMA journal_mode=WAL;
                CREATE TABLE IF NOT EXISTS addresses(id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS http_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT NOT NULL);
                INSERT OR IGNORE INTO metadata VALUES('dbVersion','0');
            """)
            initialized = con.execute("SELECT value FROM metadata WHERE key='initialized'").fetchone()
            if not initialized:
                for row in SEED:
                    con.execute("INSERT INTO addresses(id,payload) VALUES(?,?)", (row["id"], encode(row)))
                con.execute("INSERT INTO metadata VALUES('initialized',?)", (utc(),))
                con.execute("UPDATE metadata SET value='1' WHERE key='dbVersion'")
        self.write_service_event("service-start", {"pid": os.getpid(), "db": str(self.db)})

    def connect(self):
        con = sqlite3.connect(self.db, timeout=15)
        con.execute("PRAGMA busy_timeout=15000")
        return con

    @staticmethod
    def rows(con):
        return [json.loads(row[0]) for row in con.execute("SELECT payload FROM addresses ORDER BY id")]

    def version(self):
        with self.connect() as con:
            return int(con.execute("SELECT value FROM metadata WHERE key='dbVersion'").fetchone()[0])

    @staticmethod
    def bump(con):
        con.execute("UPDATE metadata SET value=CAST(value AS INTEGER)+1 WHERE key='dbVersion'")

    def append_log(self, record):
        with self.lock:
            with self.events.open("a", encoding="utf-8") as out:
                out.write(encode(record) + "\n")
                out.flush()

    def write_service_event(self, kind, detail):
        self.append_log({"event": kind, "utc": utc(), "monotonicNs": time.monotonic_ns(), **detail})

    def begin(self, request):
        with self.lock, self.connect() as con:
            request["caseId"] = self.case_id
            request["dbVersionBefore"] = self.version()
            cur = con.execute("INSERT INTO http_events(payload) VALUES(?)", (encode(request),))
            seq = cur.lastrowid
        request["seq"] = seq
        request["requestId"] = f"fixture28-{seq}"
        self.append_log({"event": "request", **request})
        return request

    def finish(self, request, response, status, started, rule, committed):
        completed = {**request, "responseUtc": utc(), "responseMonotonicNs": time.monotonic_ns(),
            "elapsedMs": round((time.monotonic() - started) * 1000, 3), "response": response,
            "httpStatus": status, "rule": rule, "committed": committed, "dbVersionAfter": self.version()}
        with self.lock, self.connect() as con:
            con.execute("UPDATE http_events SET payload=? WHERE seq=?", (encode(completed), request["seq"]))
        self.append_log({"event": "response", **completed})
        return completed

    def take_rule(self, method, path):
        with self.lock:
            for rule in self.rules:
                if rule["armed"] and rule["remaining"] > 0 and rule["method"] == method and rule["path"] == path:
                    rule["remaining"] -= 1
                    return copy.deepcopy(rule)
        return None

    def arm_success(self, method, path):
        with self.lock:
            for rule in self.rules:
                trigger = rule.get("armAfterSuccess")
                if trigger and trigger["method"] == method and trigger["path"] == path:
                    rule["armed"] = True

    def snapshot(self):
        with self.lock, self.connect() as con:
            return {"addresses": self.rows(con), "dbVersion": self.version(), "caseId": self.case_id,
                "rules": copy.deepcopy(self.rules), "maxSeq": con.execute("SELECT COALESCE(MAX(seq),0) FROM http_events").fetchone()[0]}

    def reset(self, body):
        addresses = body.get("addresses", SEED)
        if not isinstance(addresses, list):
            return failure("addresses must be an array")
        ids = set()
        for row in addresses:
            if not isinstance(row, dict) or not self.valid_payload(row) or not isinstance(row.get("id"), int) or row["id"] <= 0 or row["id"] in ids:
                return failure("Invalid seed address")
            ids.add(row["id"])
        with self.lock, self.connect() as con:
            con.execute("BEGIN IMMEDIATE")
            con.execute("DELETE FROM addresses")
            for row in addresses:
                con.execute("INSERT INTO addresses(id,payload) VALUES(?,?)", (row["id"], encode({**row, "userId": 28})))
            self.bump(con)
            self.rules = []
            self.case_id = body.get("caseId", "fixture-reset")
        return success(self.snapshot())

    def config(self, body):
        rules = body.get("rules", [])
        if not isinstance(rules, list):
            return failure("rules must be an array")
        validated = []
        for raw in rules:
            if not isinstance(raw, dict) or raw.get("method") not in ("GET", "POST") or not str(raw.get("path", "")).startswith("/app/"):
                return failure("Invalid rule method/path")
            rule = copy.deepcopy(raw)
            rule["remaining"] = int(rule.get("remaining", 1))
            rule["delayMs"] = int(rule.get("delayMs", 0))
            if not 0 <= rule["delayMs"] <= 20000 or rule["remaining"] < 0 or rule.get("failCode") == 1000:
                return failure("Invalid delay/remaining/failure code")
            trigger = rule.get("armAfterSuccess")
            if trigger and (trigger.get("method") not in ("GET", "POST") or not str(trigger.get("path", "")).startswith("/app/")):
                return failure("Invalid armAfterSuccess")
            rule["armed"] = not bool(trigger)
            validated.append(rule)
        with self.lock:
            if body.get("clearRules", False):
                self.rules = []
            self.rules.extend(validated)
            if "caseId" in body:
                self.case_id = str(body["caseId"])
        return success({"caseId": self.case_id, "rules": copy.deepcopy(self.rules)})

    @staticmethod
    def valid_payload(body):
        return isinstance(body, dict) and all(isinstance(body.get(k), str) and body[k].strip() for k in ADDRESS_FIELDS) and isinstance(body.get("isDefault"), bool)

    @staticmethod
    def arbitrate_default(con, selected_id):
        for row in FixtureState.rows(con):
            if row["id"] != selected_id and row["isDefault"]:
                row["isDefault"] = False
                con.execute("UPDATE addresses SET payload=? WHERE id=?", (encode(row), row["id"]))

    def business(self, method, path, query, body):
        """Return (JSON envelope, committed business write)."""
        if path == "/app/page/home" and method == "GET":
            return success({k: [] for k in ("banner", "category", "categoryAll", "flashSale", "recommend", "coupon", "goods")}), False
        if path == "/app/user/info/person" and method == "GET":
            return success(USER), False
        if path == "/app/order/info/userCount" and method == "GET":
            return success({k: 0 for k in ("pendingPayment", "pendingShipment", "pendingReceive", "pendingReview", "refunding", "refunded")}), False
        if path == "/app/goods/type/list" and method == "POST":
            return success([]), False
        if path == "/app/goods/info/page" and method == "POST":
            return success({"list": [], "pagination": {"page": body.get("page", 1), "size": body.get("size", 10), "total": 0}}), False
        with self.connect() as con:
            rows = self.rows(con)
            if path == "/app/page/confirmOrder" and method == "GET":
                return success({"defaultAddress": next((r for r in rows if r["isDefault"]), None), "userCoupon": []}), False
            if path == "/app/user/address/list" and method == "POST":
                return success(rows), False
            if path == "/app/user/address/default" and method == "GET":
                return success(next((r for r in rows if r["isDefault"]), None)), False
            if path == "/app/user/address/info" and method == "GET":
                try:
                    identity = int(query.get("id", ["0"])[0])
                except ValueError:
                    return failure("Invalid address id"), False
                found = next((r for r in rows if r["id"] == identity), None)
                return (success(found) if found else failure("Fixture address not found", 1404)), False
        if method != "POST" or path not in ("/app/user/address/add", "/app/user/address/update", "/app/user/address/delete"):
            return failure("Unknown fixture route", 1404), False
        with self.lock, self.connect() as con:
            con.execute("BEGIN IMMEDIATE")
            if path.endswith("/delete"):
                ids = body.get("ids")
                if not isinstance(ids, list) or not ids or any(not isinstance(i, int) or i <= 0 for i in ids):
                    return failure("Invalid delete ids"), False
                existing = {r[0] for r in con.execute("SELECT id FROM addresses")}
                if not set(ids).issubset(existing):
                    return failure("Fixture address not found", 1404), False
                con.executemany("DELETE FROM addresses WHERE id=?", [(i,) for i in ids])
                self.bump(con)
                return success(None), True
            if not self.valid_payload(body) or body.get("userId", 28) not in (0, 28):
                return failure("Incomplete fixture address"), False
            if path.endswith("/add"):
                if not re.fullmatch(r"1[3-9]\d{9}", body["phone"]):
                    return failure("手机号格式不正确"), False
                payload = {**body, "userId": 28, "createTime": utc(), "updateTime": utc()}
                cursor = con.execute("INSERT INTO addresses(payload) VALUES(?)", ("{}",))
                identity = cursor.lastrowid
                payload["id"] = identity
                con.execute("UPDATE addresses SET payload=? WHERE id=?", (encode(payload), identity))
                if payload["isDefault"]:
                    self.arbitrate_default(con, identity)
                self.bump(con)
                return success({"id": identity}), True
            identity = body.get("id")
            row = con.execute("SELECT payload FROM addresses WHERE id=?", (identity,)).fetchone()
            if not row:
                return failure("Fixture address not found", 1404), False
            original = json.loads(row[0])
            if body["phone"] != original["phone"] and not re.fullmatch(r"1[3-9]\d{9}", body["phone"]):
                return failure("手机号格式不正确"), False
            updated = {**original, **body, "id": identity, "userId": 28, "createTime": original["createTime"], "updateTime": utc()}
            con.execute("UPDATE addresses SET payload=? WHERE id=?", (encode(updated), identity))
            if updated["isDefault"]:
