            self.bump(con)
            return success(None), True


class Handler(BaseHTTPRequestHandler):
    server_version = "Fixture28/1.0"

    def log_message(self, fmt, *args):
        pass

    def do_GET(self):
        self.handle_request()

    def do_POST(self):
        self.handle_request()

    def handle_request(self):
        state = self.server.fixture_state
        started = time.monotonic()
        parsed = urlsplit(self.path)
        body = None
        parse_error = None
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if not 0 <= length <= 1024 * 1024:
                raise ValueError("Body too large")
            raw = self.rfile.read(length) if length else b""
            body = json.loads(raw) if raw else {}
            if not isinstance(body, dict):
                raise ValueError("JSON object required")
        except (ValueError, json.JSONDecodeError) as error:
            parse_error = str(error)
        request = state.begin({"utc": utc(), "monotonicNs": time.monotonic_ns(), "method": self.command,
            "url": f"http://127.0.0.1:{self.server.server_port}{self.path}", "path": parsed.path,
            "query": parse_qs(parsed.query), "body": body, "authorization": self.headers.get("Authorization", ""),
            "admin": parsed.path.startswith("/__admin/")})
        rule = None
        status = 200
        committed = False
        try:
            if self.client_address[0] != "127.0.0.1" or self.headers.get("Host") != f"127.0.0.1:{self.server.server_port}":
                status = 403
                response = failure("Loopback host required", 1403)
            elif parse_error:
                status = 400
                response = failure(parse_error)
            elif parsed.path.startswith("/__admin/"):
                response = self.admin(state, parsed, body)
            elif self.headers.get("Authorization") != TOKEN:
                status = 401
                response = failure("Public fixture identity required", 1401)
            else:
                rule = state.take_rule(self.command, parsed.path)
                if rule and rule.get("delayMs"):
                    time.sleep(rule["delayMs"] / 1000)
                if rule and "failCode" in rule:
                    response = failure(rule.get("failMessage", "fixture failure"), rule["failCode"])
                else:
                    response, committed = state.business(self.command, parsed.path, parse_qs(parsed.query), body)
                    if response["code"] == 1000:
                        state.arm_success(self.command, parsed.path)
        except Exception as error:
            status = 500
            response = failure(f"Fixture error: {type(error).__name__}: {error}", 1500)
        state.finish(request, response, status, started, rule, committed)
        encoded = encode(response).encode("utf-8")
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(encoded)))
            self.send_header("X-Fixture-Request-Id", request["requestId"])
            self.end_headers()
            self.wfile.write(encoded)
        except (BrokenPipeError, ConnectionResetError):
            state.write_service_event("client-disconnected", {"requestId": request["requestId"]})

    def admin(self, state, parsed, body):
        path = parsed.path
        if path == "/__admin/health" and self.command == "GET":
            with state.connect() as con:
                seq = con.execute("SELECT COALESCE(MAX(seq),0) FROM http_events").fetchone()[0]
            return success({"ok": True, "pid": os.getpid(), "startedAt": state.started_at, "dbPath": str(state.db), "maxSeq": seq})
        if path == "/__admin/reset" and self.command == "POST":
            return state.reset(body)
        if path == "/__admin/snapshot" and self.command == "GET":
            return success(state.snapshot())
        if path == "/__admin/config" and self.command == "POST":
            return state.config(body)
        if path == "/__admin/events" and self.command == "GET":
            after = int(parse_qs(parsed.query).get("after", ["0"])[0])
            with state.connect() as con:
                rows = con.execute("SELECT seq,payload FROM http_events WHERE seq>? ORDER BY seq", (after,)).fetchall()
            return success({"events": [{**json.loads(row[1]), "seq": row[0]} for row in rows], "nextSeq": rows[-1][0] if rows else after})
        return failure("Unknown fixture admin route", 1404)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", choices=["127.0.0.1"], default="127.0.0.1")
    parser.add_argument("--port", type=int, choices=[17028], default=17028)
    parser.add_argument("--db", type=Path, required=True)
    parser.add_argument("--events", type=Path, required=True)
    args = parser.parse_args()
    state = FixtureState(args.db, args.events)
    server = ThreadingHTTPServer((args.host, args.port), Handler)
    server.fixture_state = state
    print(encode({"event": "ready", "host": args.host, "port": args.port, "pid": os.getpid(), "db": str(state.db)}), flush=True)
    server.serve_forever()


