                if rule and rule.get("delayMs"):
                    time.sleep(rule["delayMs"] / 1000)
                if rule and "failCode" in rule:
                    response = failure(rule.get("failMessage", "fixture failure"), rule["failCode"])
                else:
                    response, committed = state.business(self.command, parsed.path, parse_qs(parsed.query), body)
                    if response["code"] == 1000:
